# Look at potential rectangular frames:
# Define a function to check if all corners and edges are 6
def check_rect(frame):
    r_min, c_min, r_max, c_max = frame
    # Check corners
    if arr[r_min, c_min] != 6 or arr[r_min, c_max] != 6:
        return False
    if arr[r_max, c_min] != 6 or arr[r_max, c_max] != 6:
        return False
    # Check top and bottom edges
    for c in range(c_min + 1, c_max):
        if arr[r_min, c] != 6 or arr[r_max, c] != 6:
            return False
    # Check left and right edges
    for r in range(r_min + 1, r_max):
        if arr[r, c_min] != 6 or arr[r, c_max] != 6:
            return False
    return True

